	"Word.DefaultWebOptions": {"displayName":"DefaultWebOptions","members":[{"name":"AllowPNG","kind":"property","returns":"Boolean","doc":{"summary":"False if PNG (Portable Network Graphics) is not allowed as an output format. Read/write Boolean.","params":[],"source":"external"}},{"name":"AlwaysSaveInDefaultEncoding","kind":"property","returns":"Boolean","doc":{"summary":"True if the default encoding is used when you save a webpage or plain text document, independent of the file's original encoding when opened. Read/write Boolean.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"Word.Application","doc":{"summary":"Returns an Application object that represents the Microsoft Word application.","params":[],"source":"external"}},{"name":"BrowserLevel","kind":"property","returns":"WdBrowserLevel","doc":{"summary":"Returns or sets a WdBrowserLevel constant that represents the level of the web browser for which you want to target new Web pages created in Microsoft Word. Read/write.","params":[],"source":"external"}},{"name":"CheckIfOfficeIsHTMLEditor","kind":"property","returns":"Boolean","doc":{"summary":"True if Microsoft Word checks to see whether an Office application is the default HTML editor when you start Word. Read/write Boolean.","params":[],"source":"external"}},{"name":"CheckIfWordIsDefaultHTMLEditor","kind":"property","returns":"Boolean","doc":{"summary":"True if Microsoft Word checks to see whether it is the default HTML editor when you start Word. Read/write Boolean.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Encoding","kind":"property","returns":"MsoEncoding","doc":{"summary":"Returns or sets the document encoding (code page or character set) to be used by the web browser when you view the saved document. Read/write MsoEncoding.","params":[],"source":"external"}},{"name":"FolderSuffix","kind":"property","returns":"String","doc":{"summary":"Returns a String that represents the folder suffix that Microsoft Word uses when you save a document as a webpage, use long file names, or save supporting files in a separate folder. Read-only.","params":[],"source":"external"}},{"name":"Fonts","kind":"property","returns":"WebPageFonts","doc":{"summary":"Returns the WebPageFonts collection representing the set of fonts that Microsoft Word uses when you open a webpage in Word.","params":[],"source":"external"}},{"name":"OptimizeForBrowser","kind":"property","returns":"Boolean","doc":{"summary":"True if Microsoft Word optimizes new Web pages created in Word for the web browser specified by the BrowserLevel property. Read/write Boolean.","params":[],"source":"external"}},{"name":"OrganizeInFolder","kind":"property","returns":"Boolean","doc":{"summary":"True if all supporting files, such as background textures and graphics, are organized in a separate folder when you save the specified document as a webpage. False if supporting files are saved in the same folder as the webpage. The default value is True. Read/write Boolean.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns an Object that represents the parent object of the specified DefaultWebOptions object.","params":[],"source":"external"}},{"name":"PixelsPerInch","kind":"property","returns":"Long","doc":{"summary":"Returns or sets the density (pixels per inch) of graphics images and table cells on a webpage. Read/write Long.","params":[],"source":"external"}},{"name":"RelyOnCSS","kind":"property","returns":"Boolean","doc":{"summary":"True if cascading style sheets (CSS) are used for font formatting when you view a saved document in a web browser. Read/write Boolean.","params":[],"source":"external"}},{"name":"RelyOnVML","kind":"property","returns":"Boolean","doc":{"summary":"True if image files are not generated from drawing objects when you save a document as a webpage. False if images are generated. The default value is False. Read/write Boolean.","params":[],"source":"external"}},{"name":"SaveNewWebPagesAsWebArchives","kind":"property","returns":"Boolean","doc":{"summary":"True for Microsoft Word to save new Web pages in the Single File Web Page (formerly known as Web Archive) format. Read/write Boolean.","params":[],"source":"external"}},{"name":"ScreenSize","kind":"property","returns":"MsoScreenSize","doc":{"summary":"Returns or sets the ideal minimum screen size (width by height, in pixels) that you should use when viewing the saved document in a web browser. Read/write MsoScreenSize.","params":[],"source":"external"}},{"name":"TargetBrowser","kind":"property","returns":"MsoTargetBrowser","doc":{"summary":"Sets or returns an MsoTargetBrowser constant representing the target browser for documents viewed in a web browser. Read/write.","params":[],"source":"external"}},{"name":"UpdateLinksOnSave","kind":"property","returns":"Boolean","doc":{"summary":"True if hyperlinks and paths to all supporting files are automatically updated before you save the document as a webpage. Read/write Boolean.","params":[],"source":"external"}},{"name":"UseLongFileNames","kind":"property","returns":"Boolean","doc":{"summary":"True if long file names are used when you save the document as a webpage. False if long file names are not used and the DOS file name format (8.3) is used. The default value is True. Read/write Boolean.","params":[],"source":"external"}}],"provenance":"Contains global application-level attributes used by Microsoft Word when you open a webpage or save a document as a webpage."},
	"Word.Diagram": {"displayName":"Diagram","members":[{"name":"Application","kind":"property","returns":"Word.Application"},{"name":"AutoFormat","kind":"property","returns":"MsoTriState"},{"name":"AutoLayout","kind":"property","returns":"MsoTriState"},{"name":"Convert","kind":"method","signature":"Convert(Type As MsoDiagramType)"},{"name":"Creator","kind":"property","returns":"Long"},{"name":"FitText","kind":"method","signature":"FitText()"},{"name":"Nodes","kind":"property","returns":"Word.DiagramNodes"},{"name":"Parent","kind":"property","returns":"Object"},{"name":"Reverse","kind":"property","returns":"MsoTriState"},{"name":"Type","kind":"property","returns":"MsoDiagramType"}]},
