	"Word.GlowFormat": {"displayName":"GlowFormat","members":[{"name":"Application","kind":"property","returns":"Word.Application","doc":{"summary":"Returns an Application object that represents the Microsoft Word application. Read-only.","params":[],"source":"external"}},{"name":"Color","kind":"property","returns":"Word.ColorFormat","doc":{"summary":"Returns a ColorFormat object that represents the color for a glow effect. Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns an Object that represents the parent object of the specified GlowFormat object.","params":[],"source":"external"}},{"name":"Radius","kind":"property","returns":"Single","doc":{"summary":"Returns or sets a Single that represents the length of the radius for a glow effect. Read/write.","params":[],"source":"external"}},{"name":"Transparency","kind":"property","returns":"Single"}],"provenance":"Represents the glow formatting for a shape or range of shapes."},
	"Word.Gridlines": {"displayName":"Gridlines","members":[{"name":"Application","kind":"property","returns":"Object","doc":{"summary":"When used without an object qualifier, returns an Application object that represents the Microsoft Word application. When used with an object qualifier, returns an Application object that represents the creator of the specified object (you can use this property with an Automation object to return t…","params":[],"source":"external"}},{"name":"Border","kind":"property","returns":"Word.ChartBorder","doc":{"summary":"Returns the border of the object. Read-only ChartBorder.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Delete","kind":"method","returns":"Variant","signature":"Delete() As Variant","doc":{"summary":"Deletes the object.","params":[],"source":"external"}},{"name":"Format","kind":"property","returns":"Word.ChartFormat","doc":{"summary":"Returns the line, fill, and effect formatting for the object. Read-only ChartFormat.","params":[],"source":"external"}},{"name":"GetProperty","kind":"method","returns":"Variant","signature":"GetProperty(ID As String) As Variant"},{"name":"Name","kind":"property","returns":"String","doc":{"summary":"Returns the name of the object. Read-only String.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent for the specified object. Read-only Object.","params":[],"source":"external"}},{"name":"Select","kind":"method","returns":"Variant","signature":"Select() As Variant","doc":{"summary":"Selects the object.","params":[],"source":"external"}},{"name":"SetProperty","kind":"method","signature":"SetProperty(ID As String, Value As Variant)"}],"provenance":"Represents major or minor gridlines on a chart axis."},
