	"Word.Revisions": {"displayName":"Revisions","members":[{"name":"AcceptAll","kind":"method","signature":"AcceptAll()","doc":{"summary":"Accepts all the tracked changes in a document or range, removes all revision marks, and incorporates the changes into the document.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"Word.Application","doc":{"summary":"Returns an Application object that represents the Microsoft Word application. Read-only.","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Returns a Long that represents the number of revisions in the collection. Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"Word.Revision","signature":"Item(Index As Long) As Revision","doc":{"summary":"Returns an individual Revisions object in a collection.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns an Object that represents the parent object of the specified Revisions object.","params":[],"source":"external"}},{"name":"RejectAll","kind":"method","signature":"RejectAll()"}],"provenance":"A collection of Revision objects that represent the changes marked with revision marks in a range or document."},
	"Word.RevisionsFilter": {"displayName":"RevisionsFilter","members":[{"name":"Markup","kind":"property","returns":"WdRevisionsMarkup","doc":{"summary":"Returns or sets a WdRevisionsMarkup constant that specifies the extent of reviewer markup displayed in the document. Read/write.","params":[],"source":"external"}},{"name":"Reviewers","kind":"property","returns":"Word.Reviewers","doc":{"summary":"Returns a Reviewers object that represents the collection of reviewers of one or more documents.","params":[],"source":"external"}},{"name":"ToggleShowAllReviewers","kind":"method","signature":"ToggleShowAllReviewers()","doc":{"summary":"Shows or hides all revisions in a document that contains comments and tracked changes.","params":[],"source":"external"}},{"name":"View","kind":"property","returns":"WdRevisionsView","doc":{"summary":"Sets or returns a WdRevisionsView constant that represents the global option that specifies whether Word displays the original version of a document or the final version, which might have revisions and formatting changes applied. Read/write.","params":[],"source":"external"}}],"provenance":"Represents the current settings related to display of reviewers' comments and revision marks in the document."},
